/* TDB native resource availability v1.0.0. Same CMS feed as nurture pages. */
(() => {
'use strict';const root=document.querySelector('[data-tdb-availability]');if(!root||root.dataset.ready)return;root.dataset.ready='true';
const slot=root.querySelector('[data-tdb-availability-value]'),button=root.querySelector('[data-tdb-availability-refresh]');if(!slot||!button)return;
let busy=false,last='',checked=0,expiry;
const formatter=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
function parseUK(date,time){if(!date||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))return NaN;const midnight=Date.parse(date+' 00:00:00 GMT');if(!Number.isFinite(midnight))return NaN;const[h,m]=time.split(':').map(Number),desired=midnight+60000*(h*60+m);const wall=t=>{const p=Object.fromEntries(formatter.formatToParts(t).map(x=>[x.type,x.value]));return Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second)};let t=desired;for(let i=0;i<2;i++)t=desired-(wall(t)-t);return wall(t)===desired?t:NaN;}
async function refresh(){if(busy)return;busy=true;button.setAttribute('aria-busy','true');const ctrl=new AbortController(),timeout=setTimeout(()=>ctrl.abort(),5000);let spin;if(!window.TDBMotion.reduced.matches)spin=button.querySelector('svg')?.animate([{transform:'rotate(0deg)'},{transform:'rotate(360deg)'}],{duration:700,iterations:Infinity});
try{const response=await fetch('/banner-settings/active',{credentials:'omit',signal:ctrl.signal,cache:'no-store'});if(!response.ok)throw Error();const doc=new DOMParser().parseFromString(await response.text(),'text/html'),field=name=>doc.querySelector('[data-banner-field="'+name+'"]')?.textContent.trim()||'';if(field('slug')!=='active')throw Error();const time=parseUK(field('next-signature-slot'),field('next-signature-uk-time'));const live=time>Date.now();last=live?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',weekday:'short',day:'numeric',month:'short'}).format(time)+' · '+new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(time):field('signature-availability-text')||'Enquire about appointments';slot.textContent=last;slot.title='Availability checked just now';checked=Date.now();clearTimeout(expiry);if(live)expiry=setTimeout(refresh,Math.min(time-Date.now()+1000,2147483647));}catch{slot.textContent=last||'Unable to check availability. Tap refresh to retry.';}finally{clearTimeout(timeout);spin?.cancel();busy=false;button.removeAttribute('aria-busy');}}
for(const type of ['click','keydown'])button.addEventListener(type,e=>{if(type==='keydown'&&!['Enter',' '].includes(e.key))return;e.preventDefault();refresh();});addEventListener('online',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()-checked>300000)refresh();});refresh();
})();
